    adcs_vec3_t s = {0.0, 0.0, 0.0};
    double total_weight = 0.0;
    size_t i;
    adcs_vec3_t u_i;
    double nrm;

    if ((samples == NULL) || (weights == NULL) || (direction == NULL) || (resultant == NULL)) {
        direction->x = 0.0;
        direction->y = 0.0;
        direction->z = 0.0;
        *resultant = 0.0;
        return ADCS_E_NULL;
    }

    if (count < 2 || count > 32) {
        direction->x = 0.0;
        direction->y = 0.0;
        direction->z = 0.0;
        *resultant = 0.0;
        return ADCS_E_RANGE;
    }

    for (i = 0; i < count; i++) {
        if (!isfinite(weights[i]) || weights[i] <= 0.0) {
            direction->x = 0.0;
            direction->y = 0.0;
            direction->z = 0.0;
            *resultant = 0.0;
            return ADCS_E_RANGE;
        }

        if (!adcs_is_finite_vec3(&samples[i])) {
            direction->x = 0.0;
            direction->y = 0.0;
            direction->z = 0.0;
            *resultant = 0.0;
            return ADCS_E_RANGE;
        }

        nrm = adcs_vec3_norm(&samples[i]);
        if (nrm <= ADCS_EPS_NORM) {
            direction->x = 0.0;
            direction->y = 0.0;
            direction->z = 0.0;
            *resultant = 0.0;
            return ADCS_E_RANGE;
        }

        u_i.x = samples[i].x / nrm;
        u_i.y = samples[i].y / nrm;
        u_i.z = samples[i].z / nrm;

        s.x += weights[i] * u_i.x;
        s.y += weights[i] * u_i.y;
        s.z += weights[i] * u_i.z;

        total_weight += weights[i];
    }

    nrm = adcs_vec3_norm(&s);
    if (nrm <= ADCS_EPS_COLLINEAR) {
        direction->x = 0.0;
        direction->y = 0.0;
        direction->z = 0.0;
        *resultant = 0.0;
        return ADCS_E_DEGENERATE;
    }

    direction->x = s.x / nrm;
    direction->y = s.y / nrm;
    direction->z = s.z / nrm;

    *resultant = nrm / total_weight;

    return ADCS_OK;
}

